// ----- CHART 1: Risk by Job Title (Line) -----
(function(){
  const ctx = document.getElementById('chartRiskByTitle').getContext('2d');
  const datasets = DATA.titles.map((t,i) => ({
    label: t, data: DATA.years.map(y => DATA.risk_by_title_year[t][String(y)]),
    borderColor: COLORS[i], backgroundColor: COLORS_LIGHT[i],
    borderWidth: t === 'Business Analyst' || t === 'Data Analyst' ? 3 : 1.5,
    tension: 0.1, pointRadius: 2
  }));
  new Chart(ctx, { type: 'line', data: { labels: DATA.years, datasets },
    options: { responsive: true, plugins: { legend: { position: 'bottom' },
      tooltip: { callbacks: { label: ctx => ctx.raw.toFixed(2) }}},
      scales: { y: { title: { display: true, text: 'AI Risk Score' }, min: 0, max: 0.9 }}}});
})();

